L21: export async function fetchStatus(input: {
L22:   url: string
L23:   signal?: AbortSignal | undefined
L24:   timeoutMs?: number
L25: }): Promise<FetchResult> {
L26:   const controller = new AbortController()
L27:   const timeout = setTimeout(() => controller.abort(), input.timeoutMs ?? DEFAULT_TIMEOUT_MS)
L28:   const forward = () => controller.abort()
L29: 
L30:   if (input.signal?.aborted) controller.abort()
L31:   input.signal?.addEventListener("abort", forward, { once: true })
L32: 
L33:   try {
L34:     const response = await fetch(input.url, {
L35:       method: "GET",
L36:       headers: { accept: "application/json" },
L37:       redirect: "follow",
L38:       signal: controller.signal,
L39:     })
L40: 
L41:     if (!response.ok) return { ok: false, error: `HTTP ${response.status}` }
L42: 
L43:     return { ok: true, payload: await response.json() }
L44:   } catch (error) {
L45:     return { ok: false, error: describe(error) }
L46:   } finally {
L47:     clearTimeout(timeout)
L48:     input.signal?.removeEventListener("abort", forward)
